import java.util.Scanner;
public class JTemperatureAboveAverage {
	public static void main(String[] args) {
		//Paso 1: Leer el numero de dias de los que debemos ingresar los datos de temperatura.
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el numero de valores de temperatura que se van a ingresar:");
		int numDays = scan.nextInt();
		//Paso 2: Leer los valores de temperatura y actualizar el total acumulado
		double[] temps = new double[numDays];
		int total = 0;
		for (int i = 0; i < numDays; i++) {
			System.out.println("Ingrese la temperatura: " );
			temps[i] = scan.nextDouble();
			total += temps[i];
		}
		scan.close();
		//Paso 3: Calcular la temperatura promedio
		double average = 0;
		if (numDays == 0) {
			System.out.println("No se ingresaron valores de temperatura.");
		} else {
			average = (double) total / numDays;			
		}
		//Paso 4: Contar el numero de dias que estan por encima de la temperatura promedio
		int above = 0;
		for (double x : temps) {
			if (x > average) {
				above++;
			}
		}
		//Paso 5: Mostrar los resultados
		System.out.println("Promedio = " + average);
		System.out.println(above + " dias por encima del promedio.");
	}
}

